insert into public.releases (id, org_id, source_item_id, title, summary, place_label, blur_x, blur_y, labels, status, created_by, signer_id, sig, published_at) values ('0a6ef6c5-c57d-4364-9b41-240a11b22005', 'f5d2bb46-a7d2-4ec5-8cc5-d735881accc0', '0e831e3b-16aa-40a7-b421-fe943a1ab6f3', 'Seven Springs holds water late into the dry season', 'Community observations over three dry seasons show the upper pools at Seven Springs holding water into late October, while the lower pool dries earlier. This summary is shared to help water planning. The detailed knowledge stays with the community.', 'Seven Springs area (location generalised)', 350, 250, array['tk-attribution','tk-verified'], 'published', '5f42f808-5ee6-4601-91e8-8c41459e82c1', '5f42f808-5ee6-4601-91e8-8c41459e82c1', 'GHIQHgB/7yv/tEF37zxwjmETYzOrM+8Pt4S2MNSY80AHZ6esebC68EVTg/jgKdK+Ef+QSiQIvwMXCSUH/rSUDg==', now() - interval '20 days');
insert into public.releases (org_id, source_item_id, title, summary, place_label, blur_x, blur_y, labels, status, created_by) values ('f5d2bb46-a7d2-4ec5-8cc5-d735881accc0', '162a207c-1ab0-4982-ab64-621a7a86813b', 'Early burns reduced late-season fire spread', 'Ranger records from 2025 suggest early dry-season burning in the north-west reduced the spread of late-season fires. Shared for land-management planning, with community approval pending.', 'North-west of Demo Country (location generalised)', 750, 350, array['tk-attribution'], 'pending', '1ce86db6-81a0-48b9-b8ee-18690348d76a');
